import unittest
from src.cart import checkout
from src.batch import allocate

class StockTests(unittest.TestCase):
    def test_success(self):
        stock = {"available": 5}
        self.assertEqual(checkout(stock, 2), {"reserved": 2})
        self.assertEqual(stock, {"available": 3})
        self.assertEqual(allocate(stock, 1), 1)
        self.assertEqual(stock, {"available": 2})

    def test_zero(self):
        for caller in (checkout, allocate):
            stock = {"available": 5}
            caller(stock, 0)
            self.assertEqual(stock, {"available": 5})

