const digits = { USD: 2, JPY: 0 };
export function formatMoney(minor, currency) {
  if (!Number.isSafeInteger(minor) || !Object.hasOwn(digits, currency)) throw new TypeError("Invalid money");
  return `${currency} ${(minor / 10 ** digits[currency]).toFixed(digits[currency])}`;
}

