import { csvCell } from "./csv.mjs";
import { withTenant } from "./http.mjs";
export async function exportActiveCustomers(request, db) {
  return withTenant(request, async (tenant) => {
    if (tenant.role !== "admin") return new Response("Forbidden", { status: 403 });
    const rows = await db.customers.findMany({ where: { tenantId: tenant.id, status: "active" }, select: { name: true, email: true } });
    const csv = ["name,email", ...rows.map(row => [row.name, row.email].map(csvCell).join(","))].join("\n");
    return new Response(csv, { headers: { "Content-Type": "text/csv", "Content-Disposition": "attachment; filename=active-customers.csv" } });
  });
}

