export async function withTenant(request, run) {
  const tenant = request.authenticatedTenant;
  if (!tenant) return new Response("Unauthorized", { status: 401 });
  try { return await run(tenant); }
  catch { return new Response("Export unavailable", { status: 503 }); }
}

